public int compress(char[] chars) {
    int n = chars.length, w = 0;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && chars[j] == chars[i]) j++;         // [i, j) is one run
        chars[w++] = chars[i];
        if (j - i > 1)
            for (char d : Integer.toString(j - i).toCharArray()) chars[w++] = d;   // multi-digit counts, digit by digit
        i = j;
    }
    return w;
}
